const _k=(($('Run').item.json.query)||{}).key;
if(_k!=='YOUR_WEBHOOK_KEY'){ return []; }

const force = !!(($('Run').item.json.body||{}).force);
const now = new Date();
const styles = [
  'lead with something concrete about their specific treatment',
  'lead with the practical reason they are about due for a visit',
  'lead with a warm, specific one-line opener about them, no pleasantry',
  'keep it very short and easy - one clear reason plus an easy way to book'
];
const SYSTEM = [
'You write ONE short re-engagement message from Birchgrove Dental (a dental practice in Cardiff) to a FORMER patient who has not been in for a while. It must read like a real person at the practice wrote it just for them - never a mass campaign.',
'RULES:',
'- Plain British English, plain text, 2 to 3 short sentences, WhatsApp length.',
'- OPEN with something specific to THEM: their name then a concrete hook tied to their last treatment or a genuine reason to come in. Do NOT open with a pleasantry.',
'- BANNED phrases, never use any of these or close variants: "hope you\u2019re doing well", "hope you are well", "just wanted to check in", "it\u2019s been a while", "we miss you", "just thinking about", "reaching out", "touch base", "how have you been".',
'- Warm, low-key, no pressure, no guilt.',
'- NEVER invent facts: no discounts, offers, prices, urgency, or medical claims, and nothing about their teeth or their last visit date you cannot know.',
'- End with a light, concrete invitation (book or reply), then on a NEW line exactly: Reply STOP to opt out.',
'- Sign off on a new line: Birchgrove Dental',
'',
'Two examples of the right tone and variety. Do NOT reuse their wording - write fresh for this patient:',
'Example A: "Hi Priya - with Invisalign it is worth a quick review now and again to make sure everything is still tracking nicely. If you would like, I can find you a slot.\nReply STOP to opt out.\nBirchgrove Dental"',
'Example B: "Hi Tom, you are probably about due for your next check-up with us. Happy to book you in whenever suits - just reply with a day that works.\nReply STOP to opt out.\nBirchgrove Dental"',
'',
'Return strict JSON: {"message": string}.'
].join('\n');
const out = []; let i = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (String(r['Opt In']||'').toLowerCase().trim() !== 'yes') continue;
  if (!force && String(r['Status']||'').trim() !== '') continue;
  const lv = new Date(r['Last Visit']);
  const months = isNaN(lv.getTime()) ? 12 : Math.round((now - lv)/(1000*60*60*24*30.44));
  if (months < 6) continue;
  const first = String(r['Name']||'').trim().split(/\s+/)[0];
  const user = 'Patient first name: ' + first + '\nLast treatment: ' + r['Last Treatment'] +
    '\nRoughly ' + months + ' months since last visit.\nApproach for this one: ' + styles[i % styles.length];
  out.push({ json: { row_number: r.row_number, Name: r['Name'], systemPrompt: SYSTEM, userPrompt: user } });
  i++;
}
return out;

// Per item: pull the drafted message; re-attach patient context via paired item.
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
let m = ''; try { m = (JSON.parse(raw).message || '').trim(); } catch (e) {}
const c = $('Filter Candidates').item.json;
return { json: { row_number: c.row_number, Name: c.Name, message: m } };

const drafted = $('Extract Message').all();
const lines = drafted.map(d => '• ' + d.json.Name + ': ' + (d.json.message||'').slice(0,60) + '…').join('\n');
return [{ json: { report: '🔁 <b>REACTIVATION</b> — ' + drafted.length + ' personalised message drafts ready (sheet: Dormant Patients)\n' + lines } }];
